CREATE TABLE `Ref_Feature_Types` (`feature_type_code` VARCHAR(100), `feature_type_name` VARCHAR(100));
CREATE TABLE `Ref_Property_Types` (`property_type_code` VARCHAR(100), `property_type_description` VARCHAR(100));
CREATE TABLE `Other_Available_Features` (`feature_id` DECIMAL(18,2), `feature_type_code` VARCHAR(100), `feature_name` VARCHAR(100), `feature_description` VARCHAR(100));
CREATE TABLE `Properties` (`property_id` DECIMAL(18,2), `property_type_code` VARCHAR(100), `date_on_market` DATETIME, `date_sold` DATETIME, `property_name` VARCHAR(100), `property_address` VARCHAR(100), `room_count` DECIMAL(18,2), `vendor_requested_price` DECIMAL(18,2), `buyer_offered_price` DECIMAL(18,2), `agreed_selling_price` DECIMAL(18,2), `apt_feature_1` VARCHAR(100), `apt_feature_2` VARCHAR(100), `apt_feature_3` VARCHAR(100), `fld_feature_1` VARCHAR(100), `fld_feature_2` VARCHAR(100), `fld_feature_3` VARCHAR(100), `hse_feature_1` VARCHAR(100), `hse_feature_2` VARCHAR(100), `hse_feature_3` VARCHAR(100), `oth_feature_1` VARCHAR(100), `oth_feature_2` VARCHAR(100), `oth_feature_3` VARCHAR(100), `shp_feature_1` VARCHAR(100), `shp_feature_2` VARCHAR(100), `shp_feature_3` VARCHAR(100), `other_property_details` VARCHAR(100));
CREATE TABLE `Other_Property_Features` (`property_id` DECIMAL(18,2), `feature_id` DECIMAL(18,2), `property_feature_description` VARCHAR(100));
